namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new()
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A timeless Neapolitan pizza with fresh mozzarella and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = ["Preheat oven to 475°F (245°C).", "Roll out dough on a floured surface.", "Spread crushed tomatoes evenly.", "Tear mozzarella and distribute over sauce.", "Bake for 10–12 minutes until crust is golden.", "Top with fresh basil and a drizzle of olive oil."],
                TotalRatings = 12, RatingSum = 52
            },
            new()
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy Roman pasta with eggs, pecorino, and guanciale.",
                Ingredients = ["Spaghetti", "Guanciale (or pancetta)", "Eggs", "Pecorino Romano", "Black pepper"],
                Steps = ["Cook spaghetti in salted boiling water until al dente.", "Crisp guanciale in a skillet over medium heat.", "Whisk eggs with grated pecorino and pepper.", "Toss hot pasta with guanciale and remove from heat.", "Pour egg mixture over pasta and toss quickly.", "Serve immediately with extra pecorino."],
                TotalRatings = 8, RatingSum = 38
            },
            new()
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken in a rich, spiced tomato-cream sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger", "Cumin", "Turmeric"],
                Steps = ["Marinate chicken in yogurt and spices for 1 hour.", "Grill or broil chicken until charred.", "Sauté onion, garlic, and ginger in a pan.", "Add tomato sauce and spices; simmer 15 minutes.", "Stir in cream and add chicken pieces.", "Simmer 10 minutes and serve over rice."],
                TotalRatings = 15, RatingSum = 70
            },
            new()
            {
                Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
                Description = "Stir-fried rice noodles with vegetables in a tangy sauce.",
                Ingredients = ["Rice noodles", "Tofu", "Bean sprouts", "Carrots", "Green onions", "Peanuts", "Lime", "Tamarind paste", "Fish sauce", "Sugar"],
                Steps = ["Soak rice noodles in warm water for 20 minutes.", "Press and cube tofu; pan-fry until golden.", "Mix tamarind paste, fish sauce, and sugar for the sauce.", "Stir-fry vegetables in a wok on high heat.", "Add noodles and sauce; toss to combine.", "Serve topped with peanuts, bean sprouts, and lime."],
                TotalRatings = 6, RatingSum = 25
            },
            new()
            {
                Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in warm tortillas with fresh toppings.",
                Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
                Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water; simmer until thickened.", "Warm tortillas in a dry skillet.", "Fill tortillas with seasoned beef.", "Top with lettuce, tomato, cheese, sour cream, and salsa.", "Serve immediately."],
                TotalRatings = 10, RatingSum = 42
            },
            new()
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh avocado dip with lime, cilantro, and a kick of jalapeño.",
                Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
                Steps = ["Halve and pit avocados; scoop into a bowl.", "Mash to desired consistency.", "Stir in diced onion, jalapeño, tomato, and cilantro.", "Add lime juice and salt to taste.", "Serve with tortilla chips."],
                TotalRatings = 9, RatingSum = 41
            },
            new()
            {
                Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Individual cakes with a molten chocolate center.",
                Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
                Steps = ["Preheat oven to 425°F (220°C). Grease ramekins.", "Melt chocolate and butter together.", "Whisk eggs, sugar, and vanilla; fold into chocolate.", "Add flour and mix until just combined.", "Pour into ramekins and bake 12–14 minutes.", "Invert onto plates and serve immediately."],
                TotalRatings = 18, RatingSum = 86
            },
            new()
            {
                Id = 8, Title = "Miso Soup", Category = "Asian",
                Description = "Light Japanese soup with tofu, seaweed, and green onions.",
                Ingredients = ["Dashi stock", "White miso paste", "Silken tofu", "Wakame seaweed", "Green onions"],
                Steps = ["Bring dashi stock to a gentle simmer.", "Add cubed tofu and rehydrated wakame.", "Remove from heat; dissolve miso paste into the broth.", "Ladle into bowls and garnish with sliced green onions."],
                TotalRatings = 5, RatingSum = 21
            },
            new()
            {
                Id = 9, Title = "Dal Tadka", Category = "Indian",
                Description = "Comforting spiced lentils finished with a sizzling tempering.",
                Ingredients = ["Yellow lentils (toor dal)", "Tomato", "Onion", "Garlic", "Cumin seeds", "Mustard seeds", "Dried red chilies", "Turmeric", "Ghee", "Cilantro"],
                Steps = ["Wash lentils and cook with turmeric until soft.", "Sauté onion, tomato, and garlic; add to lentils.", "Heat ghee in a small pan for the tadka.", "Add cumin seeds, mustard seeds, and dried chilies to ghee.", "Pour sizzling tadka over the dal.", "Garnish with cilantro and serve with rice or naan."],
                TotalRatings = 7, RatingSum = 31
            },
        ];
        _nextId = 10;
    }

    public List<RecipeCategory> GetCategories()
    {
        return
        [
            new() { Name = "Italian", Icon = "🍝", Description = "Pasta, pizza, and Mediterranean classics" },
            new() { Name = "Mexican", Icon = "🌮", Description = "Bold flavors with fresh ingredients" },
            new() { Name = "Asian", Icon = "🍜", Description = "Noodles, stir-fries, and umami-rich dishes" },
            new() { Name = "Indian", Icon = "🍛", Description = "Aromatic spices and rich curries" },
            new() { Name = "Desserts", Icon = "🍰", Description = "Sweet treats and baked goods" },
        ];
    }

    public List<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes
            .Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase))
            .ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public Recipe AddRecipe(string title, string category, string ingredients, string steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Description = $"A community-submitted {category.ToLowerInvariant()} recipe.",
            Ingredients = ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

