@page "/category/{CategoryName}"
@using RecipeHub.Services

<PageTitle>@CategoryName Recipes — RecipeHub</PageTitle>

<h1>@CategoryName Recipes</h1>
<p><a href="/">← Back to categories</a></p>

@if (Recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category yet.</div>
}
else
{
    <div class="row">
        @foreach (var recipe in Recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        <p class="text-warning mb-1">
                            @for (int i = 1; i <= 5; i++)
                            {
                                @(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")
                            }
                            <small class="text-muted">(@recipe.TotalRatings ratings)</small>
                        </p>
                        <a href="recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private List<RecipeHub.Models.Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{RecipeId:int}"
@using RecipeHub.Services

<PageTitle>@(Recipe?.Title ?? "Recipe") — RecipeHub</PageTitle>

@if (Recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
    <p><a href="/">← Back to home</a></p>
}
else
{
    <p><a href="category/@Recipe.Category">← Back to @Recipe.Category</a></p>

    <h1>@Recipe.Title</h1>
    <p class="lead text-muted">@Recipe.Description</p>

    <div class="row mt-4">
        <div class="col-md-6">
            <div class="card mb-4">
                <div class="card-header"><strong>🥘 Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in Recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-6">
            <div class="card mb-4">
                <div class="card-header"><strong>📋 Steps</strong></div>
                <ol class="list-group list-group-flush list-group-numbered">
                    @foreach (var step in Recipe.Steps)
                    {
                        <li class="list-group-item">@step</li>
                    }
                </ol>
            </div>
        </div>
    </div>

    <div class="card mt-2 mb-4">
        <div class="card-body">
            <h5 class="card-title">Rate this recipe</h5>
            <p class="text-muted mb-2">
                Average: @Recipe.AverageRating.ToString("0.0") / 5
                (@Recipe.TotalRatings ratings)
            </p>
            <StarRating RecipeId="Recipe.Id" @rendermode="InteractiveServer" />
        </div>
    </div>
}

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private RecipeHub.Models.Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(RecipeId);
    }
}

@using RecipeHub.Services
@rendermode InteractiveServer

<div class="d-flex align-items-center gap-2">
    <div style="font-size: 1.8rem; cursor: pointer; user-select: none;">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span
                @onmouseover="() => _hover = star"
                @onmouseout="() => _hover = 0"
                @onclick="() => SubmitRating(star)"
                style="color: @(star <= DisplayStars ? "#ffc107" : "#ddd"); transition: color 0.15s;">
                ★
            </span>
        }
    </div>
    @if (_submitted)
    {
        <span class="badge bg-success">Thanks! You rated @_selectedStars star@(_selectedStars != 1 ? "s" : "").</span>
    }
    else
    {
        <span class="text-muted">Click a star to rate</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private int _hover;
    private int _selectedStars;
    private bool _submitted;

    private int DisplayStars => _hover > 0 ? _hover : _selectedStars;

    private void SubmitRating(int stars)
    {
        _selectedStars = stars;
        _submitted = true;
        RecipeService.AddRating(RecipeId, stars);
    }
}

@page "/submit"
@using RecipeHub.Services
@rendermode InteractiveServer

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community.</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe "<em>@_title</em>" has been added.
        <a href="recipe/@_newRecipeId">View it here</a> or
        <button class="btn btn-link p-0" @onclick="Reset">submit another</button>.
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submitRecipe" class="needs-validation">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" @bind-Value="_model.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => _model.Title" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" @bind-Value="_model.Category" class="form-select">
                <option value="">— Select a category —</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat.Name">@cat.Icon @cat.Name</option>
                }
            </InputSelect>
            <ValidationMessage For="() => _model.Category" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" @bind-Value="_model.Ingredients" class="form-control" rows="5"
                placeholder="One ingredient per line&#10;e.g.,&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            <ValidationMessage For="() => _model.Ingredients" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" @bind-Value="_model.Steps" class="form-control" rows="5"
                placeholder="One step per line&#10;e.g.,&#10;Preheat oven to 350°F.&#10;Mix dry ingredients." />
            <ValidationMessage For="() => _model.Steps" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    [Inject] public RecipeService RecipeService { get; set; } = default!;

    private RecipeFormModel _model = new();
    private bool _submitted;
    private string _title = string.Empty;
    private int _newRecipeId;

    private void HandleSubmit()
    {
        var recipe = RecipeService.AddRecipe(
            _model.Title, _model.Category, _model.Ingredients, _model.Steps);
        _title = recipe.Title;
        _newRecipeId = recipe.Id;
        _submitted = true;
    }

